import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n >= 2:
        opp_defections = 0
        for _, o in history:
            if o == 'D':
                opp_defections += 1
        if opp_defections >= 3 and opp_defections * 2 >= n:
            return 'D'

    if n >= 2:
        if history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'

    remaining = 100 - n
    if remaining <= 3:
        return 'D'

    if remaining == 4:
        if opp_last == 'C':
            return 'D'
        return 'D'

    if opp_last == 'D' and my_last == 'D':
        if rng.random() < 0.75:
            return 'D'

    if opp_last == 'D':
        if rng.random() < 0.35:
            return 'D'

    return 'C'
